let searchStateReady=false;
function saveSearchState(){if(!searchStateReady||filterDialog.open)return;try{localStorage.setItem('pokedex_search_state',JSON.stringify({version:1,query:$('search').value,filters:Object.fromEntries(filterIds.map(id=>[id,filterValues(id)])),shiny:$('shiny').checked,related:$('includeRelated').checked}))}catch{}}
function restoreSearchState(){try{const data=JSON.parse(localStorage.getItem('pokedex_search_state')||'null');if(!data||data.version!==1)return;refreshTagOptions();if(typeof data.query==='string')$('search').value=data.query;for(const id of filterIds){const values=data.filters?.[id];if(Array.isArray(values)&&values.every(v=>typeof v==='string'))setFilterValues(id,values)}if(typeof data.shiny==='boolean')$('shiny').checked=data.shiny;if(typeof data.related==='boolean')$('includeRelated').checked=data.related}catch{}}
const GENERATION_LABELS={"Gen1":"第1世代 - カントー","Gen2":"第2世代 - ジョウト","Gen3":"第3世代 - ホウエン","Gen4":"第4世代 - シンオウ","Gen5":"第5世代 - イッシュ","Gen6":"第6世代 - カロス","Gen7":"第7世代 - アローラ","Gen8":"第8世代 - ガラル","Gen8_Hisui":"第8世代 - ヒスイ","Gen9":"第9世代 - パルデア","Gen9_ZA":"第9世代 - Z-A"};
function generationLabel(value){return GENERATION_LABELS[value]||value}
const TAG_PALETTE=[['ピーチ','#fbd0a7'],['コーラル','#fcae9f'],['ピンク','#f6acc2'],['モーブ','#ddaed3'],['パープル','#afa2d0'],['ブルー','#9db9e4'],['スカイ','#8bd4e8'],['ミント','#96d2c9'],['グリーン','#b5dbb2'],['イエロー','#efedb0'],['グレー','#b8bec6']];
function paletteColor(color){if(!color||color.toLowerCase()==='#ffffff'||!/^#[0-9a-f]{6}$/i.test(color))return '#b8bec6';const rgb=value=>[1,3,5].map(i=>parseInt(value.slice(i,i+2),16));const source=rgb(color);return TAG_PALETTE.reduce((best,item)=>{const distance=value=>rgb(value).reduce((sum,n,i)=>sum+(n-source[i])**2,0);return distance(item[1])<distance(best)?item[1]:best},TAG_PALETTE[0][1])}
// Species-level fixed genders. Reference: https://www.serebii.net/games/gender.shtml
const MALE_ONLY_SPECIES=new Set([32,33,34,106,107,128,236,237,313,381,414,475,538,539,627,628,641,642,645,859,860,861,1014,1015,1016]);
const FEMALE_ONLY_SPECIES=new Set([29,30,31,113,115,124,238,241,242,314,380,413,416,440,478,488,548,549,629,630,669,670,671,758,761,762,763,856,857,858,868,869,905,957,958,959,1017]);
function matchesGender(p,filter){if(!filter)return true;const v=String(p['性別']||'').trim(),number=Number(String(p['全国図鑑No']).replaceAll(',',''));const both=['両性','オス/メス','オス / メス'].includes(v),male=['オス','♂'].includes(v),female=['メス','♀'].includes(v);return filter==='male'?male&&!MALE_ONLY_SPECIES.has(number):filter==='female'?female&&!FEMALE_ONLY_SPECIES.has(number):filter==='both'?both:filter==='unknown'?['不明','性別不明'].includes(v):filter==='maleOnly'?MALE_ONLY_SPECIES.has(number):filter==='femaleOnly'?FEMALE_ONLY_SPECIES.has(number):false}
function filteredPokemon(){const q=$('search').value.trim().toLowerCase(),g=filterValues('gen'),c=filterValues('cat'),o=$('owned').value,r=$('registered').value,game=filterValues('game'),sh=$('shiny').checked;const matches=searchMatches(q);return db.pokemon.filter(p=>matchesGender(p,$('genderFilter').value)&&(!matches||matches.has(key(p)))&&(!filterValues('tagFilter').length||filterValues('tagFilter').some(tag=>personalTags(p).includes(tag)))&&(!$('memoFilter').value||Boolean(personalMemo(p).trim())===($('memoFilter').value==='yes'))&&(!g.length||g.includes(p['世代']))&&(!c.length||c.some(value=>categories(p).includes(value)))&&(!r||(regValue(effective(p,sh?'shinyRegistered':'registered'))===r&&!locked(effective(p,sh?'shinyRegistered':'registered'))))&&(!game.length||game.some(value=>/^(yes|true|1)$/i.test(String(p['実装 ('+value+')']||'').trim())))&&(!o||(sh?effective(p,'shiny'):effective(p,'owned'))===o))}

let relationSource=null,relationGraph=null;
function searchMatches(q){if(!q)return null;const matches=new Set(db.pokemon.filter(p=>p['名前'].toLowerCase().includes(q)||String(p['全国図鑑No']).includes(q)||personalMemo(p).toLowerCase().includes(q)||personalTags(p).some(tag=>tag.toLowerCase().includes(q))).map(key));if(!$('includeRelated').checked)return matches;if(relationSource!==db.pokemon){relationSource=db.pokemon;relationGraph=new Map(db.pokemon.map(p=>[key(p),new Set()]));const byName=new Map(),byNumber=new Map();for(const p of db.pokemon){const names=byName.get(p['名前'])||[];names.push(p);byName.set(p['名前'],names);const forms=byNumber.get(p['全国図鑑No'])||[];forms.push(p);byNumber.set(p['全国図鑑No'],forms)}const connect=(a,b)=>{relationGraph.get(key(a)).add(key(b));relationGraph.get(key(b)).add(key(a))};for(const forms of byNumber.values())for(const p of forms.slice(1))connect(forms[0],p);for(const p of db.pokemon)for(const col of ['進化系','すがた違い'])for(const name of String(p[col]||'').split(/[,、，]/).map(v=>v.trim()).filter(Boolean))for(const other of byName.get(name)||[])connect(p,other)}const queue=[...matches];for(let i=0;i<queue.length;i++)for(const id of relationGraph.get(queue[i])||[])if(!matches.has(id)){matches.add(id);queue.push(id)}return matches}

const GAMES=['ピカブイ','剣盾','BDSP','アルセウス','SV','Z-A','FRLG'];
const store='pokedex_personal_v2';
let db={pokemon:[],states:{},tags:[],tagColors:{},demo:false},active=null;
