let showListTags=true;try{showListTags=localStorage.getItem('pokedex_show_list_tags')!=='false'}catch{}
let bulkMode=false,bulkShiny=false;const bulkSelection=new Set();const detailTagCandidates=new Map();
function detailTagsFor(p,sh){const id=key(p)+'|'+Boolean(sh);if(!detailTagCandidates.has(id))detailTagCandidates.set(id,new Set());return detailTagCandidates.get(id)}
let legacyData=null,storageWarning='',hasPersonalData=false;
function readStored(name){const raw=localStorage.getItem(name);return raw?JSON.parse(raw):null}
try{const personal=readStored(store);if(personal){if(personal.version!==2||!personal.states||typeof personal.states!=='object'||Array.isArray(personal.states))throw Error('保存形式が不正です');db.states=personal.states;db.tags=cleanTags(personal.tags||[]);db.tagColors=normalizeTagColors(personal.tagColors);hasPersonalData=true}legacyData=readStored('pokedex_v1')}catch{storageWarning='保存済みの個人データを読み込めませんでした。バックアップを確認してください。'}
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function key(p){return p.ID}function state(p){return db.states[key(p)]||{registered:p['HOME 図鑑登録']||'未登録',shinyRegistered:p['HOME 図鑑登録 (色違い)']||'No',owned:p['HOME 所持状況']||'未所持',shiny:p['HOME 所持状況 (色違い)']||'未所持'}}function locked(v){return ['不要','不可'].includes(String(v??'').trim())}
function regValue(v){return isRegistered(v)?'Yes':'No'}
function effective(p,field){const columns={registered:'HOME 図鑑登録',shinyRegistered:'HOME 図鑑登録 (色違い)',owned:'HOME 所持状況',shiny:'HOME 所持状況 (色違い)'};const source=p[columns[field]]||'';if(locked(source))return source;const edited=db.states[key(p)]?.[field];return edited===undefined?(source||(['registered','shinyRegistered'].includes(field)?'No':'未所持')):locked(edited)?source||'No':edited}
function normalizeTagColors(value){if(value===undefined)return {};if(!value||typeof value!=='object'||Array.isArray(value))throw Error('タグカラーの形式が不正です');const result=Object.create(null);for(const [tag,color] of Object.entries(value)){if(typeof color!=='string'||!/^#[0-9a-f]{6}$/i.test(color))throw Error('タグカラーが不正です');result[tag]=paletteColor(color)}return result}
function tagStyle(tag){const color=paletteColor(db.tagColors?.[tag]);return '--tag-color:'+color+';--tag-background:'+color+'80;--tag-border:'+color+';--tag-ring:'+color+';'}
function applyTagStyle(el,tag){el.style.cssText=tagStyle(tag);el.classList.toggle('tag-colored',!!tagStyle(tag))}
function cleanTags(values){if(!Array.isArray(values)||values.some(v=>typeof v!=='string'))throw Error('タグの形式が不正です');return [...new Set(values.map(v=>v.trim()).filter(Boolean))]}
function personalTags(p,sh=$('shiny').checked){return cleanTags(db.states[key(p)]?.[sh?'shinyTags':'tags']||[])}
function allTags(){return cleanTags(Object.values(db.states).flatMap(s=>[...(Array.isArray(s?.tags)?s.tags:[]),...(Array.isArray(s?.shinyTags)?s.shinyTags:[])]))}
function refreshTagOptions(){const select=$('tagFilter');if(!select)return;const old=filterValues('tagFilter');select.innerHTML=allTags().sort((a,b)=>a.localeCompare(b,'ja')).map(tag=>'<option value="'+esc(tag)+'">'+esc(tag)+'</option>').join('');setFilterValues('tagFilter',old);if($('bulkTagSuggestions'))$('bulkTagSuggestions').innerHTML=allTags().map(tag=>'<option value="'+esc(tag)+'"></option>').join('')}
function renderDetailTags(p,sh=$('shiny').checked){const root=$('detailTags'),select=$('existingTag');root.replaceChildren();for(const tag of personalTags(p,sh)){const button=document.createElement('button');button.type='button';button.className='filter-choice personal-tag';button.textContent=tag;const on=personalTags(p,sh).includes(tag);button.setAttribute('aria-pressed',String(on));button.classList.toggle('is-selected',on);applyTagStyle(button,tag);button.onclick=()=>{const tags=personalTags(p,sh);storeDetailTags(p,on?tags.filter(t=>t!==tag):[...tags,tag],sh)};root.append(button)}root.append(select);const available=cleanTags([...allTags(),...[...detailTagCandidates.values()].flatMap(tags=>[...tags])]).filter(tag=>!personalTags(p,sh).includes(tag)).sort((a,b)=>a.localeCompare(b,'ja'));select.innerHTML='<option value="">既存タグを追加</option>'+available.map(tag=>'<option value="'+esc(tag)+'">'+esc(tag)+'</option>').join('');select.disabled=!available.length;select.onchange=()=>{const tag=select.value;if(tag)storeDetailTags(p,[...personalTags(p,sh),tag],sh)}}
function storeDetailTags(p,tags,sh){const candidates=cleanTags([...personalTags(p,sh),...tags]);const previous=db.states,oldTags=db.tags;db.states={...previous,[key(p)]:{...state(p),[sh?'shinyTags':'tags']:cleanTags(tags)}};db.tags=allTags();try{save()}catch{db.states=previous;db.tags=oldTags;$('detailTagStatus').textContent='保存できませんでした。変更は反映していません。';return}for(const tag of candidates)detailTagsFor(p,sh).add(tag);render();renderDetailTags(p,sh);$('detailTagStatus').textContent=''}
function personalMemo(p,sh=$('shiny').checked){const value=db.states[key(p)]?.[sh?'shinyMemo':'memo'];return typeof value==='string'?value:''}
function save(){localStorage.setItem(store,JSON.stringify({version:2,states:db.states,tags:allTags(),tagColors:db.tagColors}))}function categories(p){return String(p['カテゴリ']||'').split(/[,、，]/).map(x=>x.trim()).filter(Boolean)}function displayName(name){const m=String(name||'').match(/^(.+?)（([^（）]+)）$/);return m?`<span class="pokemon-name">${esc(m[1])}</span><span class="form-name">${esc(m[2])}</span>`:`<span class="pokemon-name">${esc(name)}</span>`}
function pokemonImage(p,sh,lazy=true){const source=String((sh&&p?.['画像 (色違い)'])||p?.['画像']||'').trim();return `<img ${lazy?'loading="lazy" ':''}src="${esc(source||'assets/images/hatena.svg')}" alt="${source?'':'画像なし'}" onerror="this.onerror=null;this.src='assets/images/hatena.svg';this.alt='画像なし'">`}
function thumbnailClass(p,sh){const value=effective(p,sh?'shinyRegistered':'registered');return !locked(value)&&!isRegistered(value)?'is-unregistered':''}
function shinyRegisteredValue(p,s){return effective(p,'shinyRegistered')}function isRegistered(value){return ['yes','登録済','true','1'].includes(String(value||'').trim().toLowerCase())}function isOwned(value){return String(value||'').trim()==='所持'}function statusIcon(file,active,label){return `<span class="status-icon ${active?'is-active':'is-inactive'}" title="${label}" aria-label="${label}"><img src="${file}" alt=""></span>`}function filterValues(id){return [...$(id).selectedOptions].map(option=>option.value).filter(Boolean)}
function setFilterValues(id,values){for(const option of $(id).options)option.selected=values.includes(option.value);if(!values.length)$(id).selectedIndex=-1}
function selectValues(){for(const [id,col] of [['gen','世代'],['cat','カテゴリ'],['game',null]]){const el=$(id),old=filterValues(id);let values=id==='game'?[...GAMES]:[...new Set(db.pokemon.flatMap(p=>id==='cat'?categories(p):[p[col]]).filter(Boolean))];if(id==='cat'){const ranks=new Map();for(const p of db.pokemon){const raw=String(p['ソート用番号']||'').replaceAll(',','').trim();const rank=raw&&Number.isFinite(Number(raw))?Number(raw):Infinity;for(const category of categories(p))ranks.set(category,Math.min(ranks.get(category)??Infinity,rank))}values.sort((a,b)=>ranks.get(a)-ranks.get(b))}else if(id==='gen'){const order=Object.keys(GENERATION_LABELS);values.sort((a,b)=>(order.includes(a)?order.indexOf(a):Infinity)-(order.includes(b)?order.indexOf(b):Infinity))}el.innerHTML=values.map(v=>'<option value="'+esc(v)+'">'+esc(id==='gen'?generationLabel(v):v)+'</option>').join('');setFilterValues(id,old)}}
function syncFilterButtons(){for(const group of document.querySelectorAll('.filter-choices')){const select=$(group.dataset.filter);const options=[...select.options].filter(option=>option.value);const signature=JSON.stringify(options.map(option=>[option.value,option.textContent]));if(group.dataset.options!==signature){group.replaceChildren();for(const option of options){const button=document.createElement('button');button.type='button';button.className='filter-choice';button.textContent=option.textContent;button.dataset.value=option.value;button.onclick=()=>{if(select.multiple){const current=[...select.options].find(item=>item.value===option.value);current.selected=!current.selected;}else setFilterValues(select.id,select.value===option.value?[]:[option.value]);select.dispatchEvent(new Event('change',{bubbles:true}))};group.append(button)}group.dataset.options=signature}for(const button of group.children){const selected=filterValues(select.id).includes(button.dataset.value);button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));if(select.id==='tagFilter')applyTagStyle(button,button.dataset.value)}}}
