function updateFilterAppearance(){refreshTagOptions();syncFilterButtons();for(const id of ['search','gen','cat','registered','game','owned','memoFilter','tagFilter','genderFilter'])$(id).classList.toggle('filter-active',filterValuesForAppearance(id))}function render(){const shinyBtn=$('shinyButton');if(shinyBtn){const on=$('shiny').checked;shinyBtn.classList.toggle('is-on',on);shinyBtn.setAttribute('aria-pressed',String(on))}updateFilterAppearance();refreshFilterButton();const sh=$('shiny').checked;const rows=filteredPokemon();$('grid').classList.toggle('show-list-tags',showListTags);$('grid').classList.toggle('show-list-games',showListGames);$('count').textContent=`${rows.length} 件`;$('demoNote').hidden=!db.demo;$('grid').innerHTML=rows.map(p=>{let s=state(p),owned=(sh?effective(p,'shiny'):effective(p,'owned'))==='所持';return `<button class="poke ${bulkMode?'is-selectable':''} ${bulkSelection.has(key(p))?'is-selected':''}" data-id="${esc(key(p))}" ${bulkMode?'aria-pressed="'+bulkSelection.has(key(p))+'"':''}><div class="art ${thumbnailClass(p,sh)}"><span class="list-gender" aria-label="性別">${genderLabel(p['性別'])}</span><span class="num">No.${esc(p['全国図鑑No'])}</span><span class="status-icons">${statusIcon('assets/images/bookmark-fill.svg',isRegistered(sh?effective(p,'shinyRegistered'):effective(p,'registered')),'図鑑登録'+(sh?'（色違い）':'')+'：'+(sh?shinyRegisteredValue(p,s):effective(p,'registered')))}${(sh?effective(p,'shiny'):effective(p,'owned'))==='不可'?'':statusIcon('assets/images/archive-fill.svg',owned,'所持状況：'+(sh?effective(p,'shiny'):effective(p,'owned')))}</span>${pokemonImage(p,sh)}${personalMemo(p).trim()?'<span class="memo-indicator" title="メモあり" aria-label="メモあり"><img src="assets/images/pencil-fill.svg" alt=""></span>':''}</div><div class="info ${thumbnailClass(p,sh)}"><div class="name">${displayName(p['名前'])}</div>${showListGames?'<div class="list-games" aria-label="実装タイトル">'+GAMES.filter(game=>/^(yes|true|1)$/i.test(String(p['実装 ('+game+')']||'').trim())).map(game=>'<span>'+esc(game)+'</span>').join('')+'</div>':''}${showListTags&&personalTags(p,sh).length?'<div class="list-tags" aria-label="タグ">'+personalTags(p,sh).map(tag=>'<span class="list-tag" style="'+tagStyle(tag)+'">'+esc(tag)+'</span>').join('')+'</div>':''}</div></button>`}).join('')||'<div class="empty">該当するポケモンがありません</div>';refreshDetailNavigation();refreshBulkUI();saveSearchState()}

