for(const [id,title,description] of [['backupBtn','個人データのバックアップ','図鑑登録・所持状況・メモ・タグをJSONファイルに保存します。'],['restoreBtn','個人データの復元','バックアップファイルから図鑑登録・所持状況・メモを復元します。']]){const section=document.createElement('section');const heading=document.createElement('h3');heading.textContent=title;const help=document.createElement('p');help.className='help';help.textContent=description;section.append(heading,help,$(id));settingsDialog.querySelector('.filter-dialog-body').append(section)}

const tagDisplaySection=document.createElement('section');tagDisplaySection.innerHTML='<h3>一覧の表示</h3><label class="tag-display-setting"><input type="checkbox" id="showListTags">一覧にタグを表示</label><p class="help" id="tagDisplayStatus" role="status"></p>';settingsDialog.querySelector('.filter-dialog-body').prepend(tagDisplaySection);$('showListTags').checked=showListTags;$('showListTags').onchange=()=>{const next=$('showListTags').checked;try{localStorage.setItem('pokedex_show_list_tags',String(next));showListTags=next;render();$('tagDisplayStatus').textContent=''}catch{$('showListTags').checked=showListTags;$('tagDisplayStatus').textContent='表示設定を保存できませんでした。'}};



const gamesSetting=document.createElement('label');gamesSetting.className='tag-display-setting';gamesSetting.innerHTML='<input type="checkbox" id="showListGames">一覧に実装タイトルを表示';tagDisplaySection.insertBefore(gamesSetting,$('showListTags').closest('label'));$('showListGames').checked=showListGames;$('showListGames').onchange=()=>{const next=$('showListGames').checked;try{localStorage.setItem('pokedex_show_list_games',String(next));showListGames=next;render();$('tagDisplayStatus').textContent=''}catch{$('showListGames').checked=showListGames;$('tagDisplayStatus').textContent='表示設定を保存できませんでした。'}};

const tagManager=document.createElement('section');tagManager.className='tag-manager';tagManager.innerHTML='<h3>タグ管理</h3><p class="help">削除すると、すべての項目からタグを外します。</p><div id="tagManagerRows"></div><p id="tagManagerStatus" class="help" role="status"></p>';settingsDialog.querySelector('.filter-dialog-body').append(tagManager);
function renderTagManager(){const root=$('tagManagerRows');root.replaceChildren();const tags=allTags().sort((a,b)=>a.localeCompare(b,'ja'));if(!tags.length){const text=document.createElement('p');text.className='help';text.textContent='使用中のタグはありません。';root.append(text)}for(const tag of tags){const row=document.createElement('div');row.className='tag-manager-row';const name=document.createElement('input');name.type='text';name.value=tag;name.setAttribute('aria-label',tag+'の名前');let selected=paletteColor(db.tagColors?.[tag]);const originalColor=selected;const colorToggle=document.createElement('button');colorToggle.type='button';colorToggle.className='tag-color-toggle';colorToggle.style.backgroundColor=selected;colorToggle.setAttribute('aria-label',tag+'のカラーを選択');colorToggle.setAttribute('aria-expanded','false');name.style.setProperty('--selected-tag-color',selected);const palette=document.createElement('div');palette.className='tag-palette';palette.hidden=true;colorToggle.onclick=()=>{const open=palette.hidden;for(const other of root.querySelectorAll('.tag-palette'))other.hidden=true;for(const other of root.querySelectorAll('.tag-color-toggle'))other.setAttribute('aria-expanded','false');palette.hidden=!open;colorToggle.setAttribute('aria-expanded',String(open))};palette.setAttribute('role','group');palette.setAttribute('aria-label',tag+'のカラー');for(const [label,value] of TAG_PALETTE){const swatch=document.createElement('button');swatch.type='button';swatch.className='tag-swatch';swatch.style.backgroundColor=value;swatch.title=label;swatch.setAttribute('aria-label',label);swatch.dataset.color=value;swatch.setAttribute('aria-pressed',String(value===selected));swatch.onclick=()=>{selected=value;for(const button of palette.children)button.setAttribute('aria-pressed',String(button.dataset.color===selected));refreshDirty()};palette.append(swatch)}const saveButton=document.createElement('button');saveButton.type='button';saveButton.className='btn';saveButton.textContent='保存';saveButton.disabled=true;saveButton.onclick=()=>manageTag(tag,name.value,selected,false);function refreshDirty(){const dirty=name.value.trim()!==tag||selected!==originalColor;saveButton.classList.toggle('has-unsaved-changes',dirty);saveButton.disabled=!dirty;saveButton.title=dirty?'変更を保存':'保存';name.style.setProperty('--selected-tag-color',selected);colorToggle.style.backgroundColor=selected}name.oninput=refreshDirty;const remove=document.createElement('button');remove.type='button';remove.className='btn tag-delete';remove.textContent='削除';remove.onclick=()=>{if(confirm('「'+tag+'」をすべての項目から削除しますか？'))manageTag(tag,'',null,true)};row.append(colorToggle,name,saveButton,remove,palette);root.append(row)}}
function manageTag(oldName,newName,color,remove){newName=newName.trim();const status=$('tagManagerStatus');if(!remove&&!newName){status.textContent='タグ名を入力してください。';return}if(!remove&&newName!==oldName&&allTags().includes(newName)){status.textContent='同じ名前のタグがすでにあります。別の名前を指定してください。';return}const previous=db.states,oldColors=db.tagColors,oldTags=db.tags,selected=filterValues('tagFilter');const next={...previous};for(const [id,entry] of Object.entries(previous)){const updated={...entry};for(const field of ['tags','shinyTags'])if(Array.isArray(entry[field]))updated[field]=cleanTags(remove?entry[field].filter(tag=>tag!==oldName):entry[field].map(tag=>tag===oldName?newName:tag));next[id]=updated}const colors={...oldColors};delete colors[oldName];if(!remove&&color)colors[newName]=color;db.states=next;db.tagColors=colors;db.tags=allTags();try{save()}catch{db.states=previous;db.tagColors=oldColors;db.tags=oldTags;status.textContent='保存できませんでした。変更は反映していません。';return}refreshTagOptions();setFilterValues('tagFilter',remove?selected.filter(tag=>tag!==oldName):selected.map(tag=>tag===oldName?newName:tag));render();renderTagManager();status.textContent=remove?'タグを削除しました。':''}

const settingsOpen=document.createElement('button');settingsOpen.type='button';settingsOpen.className='btn';settingsOpen.id='settingsOpen';settingsOpen.innerHTML='<img src="assets/images/gear-fill.svg" alt="" width="20" height="20">';settingsOpen.setAttribute('aria-label','設定');settingsOpen.title='設定';settingsOpen.setAttribute('aria-haspopup','dialog');document.querySelector('.head .actions').append(settingsOpen);
