function closeSettings(){settingsDialog.close();settingsOpen.focus()}
settingsDialog.querySelector('.filter-close').onclick=closeSettings;settingsDialog.addEventListener('cancel',e=>{e.preventDefault();closeSettings()});settingsDialog.addEventListener('click',e=>{if(e.target===settingsDialog){const r=settingsDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSettings()}});


const bulkToggle=document.createElement('button');bulkToggle.type='button';bulkToggle.id='bulkToggle';bulkToggle.className='btn';bulkToggle.textContent='複数選択';bulkToggle.setAttribute('aria-pressed','false');document.querySelector('.summary').append(bulkToggle);
const bulkPanel=document.createElement('dialog');bulkPanel.id='bulkPanel';bulkPanel.className='filter-dialog bulk-dialog';bulkPanel.setAttribute('aria-labelledby','bulkTitle');
bulkPanel.innerHTML='<div class="filter-dialog-head"><h2 id="bulkTitle">一括編集</h2><span id="bulkCount" class="bulk-header-count"></span><button type="button" class="filter-close" id="bulkClose" aria-label="一括編集を閉じる">×</button></div><div class="filter-dialog-body"><div class="bulk-actions"><label>図鑑登録<select id="bulkRegistered"><option value="">変更しない</option><option value="Yes">登録</option><option value="No">未登録</option></select></label><label>所持状況<select id="bulkOwned"><option value="">変更しない</option><option value="所持">所持</option><option value="未所持">未所持</option></select></label><section class="bulk-tag-section"><h3>タグ</h3><div id="bulkTagRows"></div><div class="tag-add-row"><input id="bulkNewTag" aria-label="新しいタグ名" placeholder="新しいタグ名"><button type="button" class="btn" id="bulkAddTag">追加</button></div></section></div><div id="bulkStatus" class="help" role="status"></div></div><div class="filter-dialog-foot"><button type="button" class="btn primary" id="bulkApply">選択した項目に適用</button></div>';
document.body.append(bulkPanel);
const summary=document.querySelector('.summary');document.querySelector('header').append(summary);$('count').after(relatedRow);
const bulkEdit=document.createElement('button');bulkEdit.type='button';bulkEdit.id='bulkEdit';bulkEdit.className='btn primary';bulkEdit.textContent='0件を編集';bulkEdit.hidden=true;bulkEdit.setAttribute('aria-haspopup','dialog');summary.insertBefore(bulkEdit,bulkToggle);
const selectedCount=document.createElement('span');selectedCount.id='selectedCount';selectedCount.hidden=true;summary.insertBefore(selectedCount,bulkEdit);
const bulkAllToggle=document.createElement('button');bulkAllToggle.type='button';bulkAllToggle.id='bulkAllToggle';bulkAllToggle.className='btn';bulkAllToggle.textContent='すべて選択';bulkAllToggle.hidden=true;summary.insertBefore(bulkAllToggle,bulkEdit);bulkAllToggle.onclick=()=>{const rows=filteredPokemon();const all=rows.length>0&&rows.every(p=>bulkSelection.has(key(p)));for(const p of rows){if(all)bulkSelection.delete(key(p));else bulkSelection.add(key(p))}render()};

bulkEdit.onclick=()=>{bulkTagDraft.clear();$('bulkNewTag').value='';$('bulkStatus').textContent='';renderBulkTags();refreshBulkUI();bulkPanel.showModal()};function closeBulkEditor(){bulkPanel.close();bulkEdit.focus()}
$('bulkClose').onclick=closeBulkEditor;bulkPanel.addEventListener('cancel',e=>{e.preventDefault();closeBulkEditor()});bulkPanel.addEventListener('click',e=>{if(e.target===bulkPanel){const r=bulkPanel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeBulkEditor()}});

const bulkTagDraft=new Map();
function bulkTagState(tag){const items=db.pokemon.filter(p=>bulkSelection.has(key(p)));const count=items.filter(p=>personalTags(p,bulkShiny).includes(tag)).length;return count===0?false:count===items.length?true:'mixed'}
function renderBulkTags(){const root=$('bulkTagRows');root.replaceChildren();const tags=cleanTags([...allTags(),...bulkTagDraft.keys()]);for(const tag of tags){const state=bulkTagDraft.has(tag)?bulkTagDraft.get(tag):bulkTagState(tag);const row=document.createElement('button');row.type='button';row.className='bulk-tag-row';row.setAttribute('role','checkbox');row.setAttribute('aria-label',tag);row.setAttribute('aria-checked',String(state));row.disabled=!bulkSelection.size;const label=document.createElement('span');label.className='list-tag';label.style.cssText=tagStyle(tag);label.textContent=tag;const icon=document.createElement('img');icon.alt='';icon.src='assets/images/'+(state==='mixed'?'dash-square-fill.svg':state?'check-square-fill.svg':'square.svg');row.append(label,icon);row.onclick=()=>{const current=bulkTagDraft.has(tag)?bulkTagDraft.get(tag):bulkTagState(tag);const next=current==='mixed'?false:!current;if(next===bulkTagState(tag))bulkTagDraft.delete(tag);else bulkTagDraft.set(tag,next);renderBulkTags();refreshBulkUI()};root.append(row)}}
$('bulkAddTag').onclick=()=>{const tag=$('bulkNewTag').value.trim();if(!tag||!bulkSelection.size)return;bulkTagDraft.set(tag,true);$('bulkNewTag').value='';renderBulkTags();refreshBulkUI()};$('bulkNewTag').onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();$('bulkAddTag').click()}};

function refreshBulkUI(){if(!$('bulkPanel'))return;bulkAllToggle.hidden=!bulkMode;const visible=filteredPokemon();const allSelected=visible.length>0&&visible.every(p=>bulkSelection.has(key(p)));bulkAllToggle.disabled=!visible.length;bulkAllToggle.setAttribute('aria-pressed',String(allSelected));bulkAllToggle.textContent=allSelected?'すべて解除':'すべて選択';for(const id of ['bulkRegistered','bulkOwned'])$(id).classList.toggle('is-changing',!!$(id).value);bulkEdit.hidden=!bulkMode;bulkEdit.disabled=!bulkSelection.size;selectedCount.hidden=true;bulkEdit.textContent=bulkSelection.size+'件を編集';bulkToggle.textContent=bulkMode?'×':'複数選択';bulkToggle.classList.toggle('is-exit',bulkMode);bulkToggle.setAttribute('aria-label',bulkMode?'選択を終了':'複数選択');bulkToggle.title=bulkMode?'選択を終了':'複数選択';bulkToggle.setAttribute('aria-pressed',String(bulkMode));$('shinyButton').disabled=bulkMode;$('bulkCount').textContent=bulkSelection.size+'件選択中';$('bulkApply').disabled=!bulkSelection.size||!($('bulkRegistered').value||$('bulkOwned').value||bulkTagDraft.size);}
bulkToggle.onclick=()=>{if(bulkPanel.open)bulkPanel.close();bulkMode=!bulkMode;bulkShiny=$('shiny').checked;bulkSelection.clear();$('bulkRegistered').value='';$('bulkOwned').value='';bulkTagDraft.clear();$('bulkNewTag').value='';$('bulkStatus').textContent='';render()};
for(const id of ['bulkRegistered','bulkOwned'])$(id).onchange=refreshBulkUI;
$('bulkApply').onclick=()=>{if(!bulkMode||!bulkSelection.size)return;const registration=$('bulkRegistered').value,ownership=$('bulkOwned').value;if(!registration&&!ownership&&!bulkTagDraft.size)return;const previous=db.states,next={...previous};let changed=0,skipped=0;for(const p of db.pokemon){const id=key(p);if(!bulkSelection.has(id))continue;const entry={...state(p)};let touched=false;for(const [field,value] of [[bulkShiny?'shinyRegistered':'registered',registration],[bulkShiny?'shiny':'owned',ownership]]){if(!value)continue;if(locked(effective(p,field))){skipped++;continue}if(effective(p,field)!==value){entry[field]=value;touched=true}}if(bulkTagDraft.size){const tags=personalTags(p,bulkShiny);let updated=[...tags];for(const [tag,on] of bulkTagDraft){updated=on?cleanTags([...updated,tag]):updated.filter(value=>value!==tag)}if(JSON.stringify(tags)!==JSON.stringify(updated)){entry[bulkShiny?'shinyTags':'tags']=updated;touched=true}}if(touched){next[id]=entry;changed++}}const oldTags=db.tags;db.states=next;try{save()}catch{db.states=previous;db.tags=oldTags;$('bulkStatus').textContent='保存できませんでした。変更は反映していません。';return}bulkTagDraft.clear();renderBulkTags();$('bulkStatus').textContent=changed+'件を変更しました。'+(skipped?'登録不要・所持不可の'+skipped+'項目は変更していません。':'');render();closeBulkEditor();bulkToggle.focus()};

function opts(current,choices){return [...new Set([current,...choices].filter(Boolean))].map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function detailTitleName(name,sh){const match=String(name||'').match(/^(.+?)（([^（）]+)）$/);const base=match?match[1]:name;return '<span class="detail-title-name"><span class="detail-name-main"><span class="pokemon-name">'+esc(base)+'</span>'+(sh?'<img src="assets/images/stars.svg" class="detail-title-shiny" alt="色違い" title="色違い">':'')+'</span>'+(match?'<span class="form-name">'+esc(match[2])+'</span>':'')+'</span>'}
function genderLabel(value){const v=String(value||'').trim();const badge=(gender,label)=>'<span class="tag gender-badge" title="'+label+'"><span class="gender-icon '+gender+'" role="img" aria-label="'+label+'"></span></span>';if(['両性','オス/メス','オス / メス'].includes(v))return badge('male','オス')+badge('female','メス');if(['オス','♂'].includes(v))return badge('male','オス');if(['メス','♀'].includes(v))return badge('female','メス');if(['不明','性別不明'].includes(v))return '<span class="gender-unknown">性別不明</span>';return '<span class="tag">'+esc(v||'—')+'</span>'}
function detailNeighbors(id){const rows=filteredPokemon();const index=rows.findIndex(p=>key(p)===id);if(index>=0)return {previous:rows[index-1]||null,next:rows[index+1]||null};const positions=new Map(db.pokemon.map((p,i)=>[key(p),i]));const anchor=positions.get(id);return {previous:rows.filter(p=>positions.get(key(p))<anchor).at(-1)||null,next:rows.find(p=>positions.get(key(p))>anchor)||null}}
function refreshDetailNavigation(){if(!active||!$('detailPrev'))return;const {previous,next}=detailNeighbors(active);const sh=$('detailShiny').getAttribute('aria-pressed')==='true';for(const [id,target] of [['detailPrev',previous],['detailNext',next]]){$(id).disabled=!target;$(id).onclick=()=>{if(target)openDetail(key(target),sh)}}}
function openDetail(id,detailShiny=null){let p=db.pokemon.find(x=>key(x)===id);if(!p)return;if(!active)detailTagCandidates.clear();active=id;const s=state(p),sh=detailShiny===null?$('shiny').checked:detailShiny;
const regControl=(field,label)=>{const v=effective(p,field),fixed=locked(v),yes=isRegistered(v);return `<button type="button" class="status-control ${fixed?'is-fixed':yes?'is-active':''}" ${fixed?'disabled':''} data-toggle="${field}" aria-pressed="${yes}" title="${fixed?'変更できません':label+'を切り替える'}">${statusIcon('assets/images/bookmark-fill.svg',yes,label)}<span class="status-control-label">HOME 図鑑</span><span class="status-control-value">${fixed?'登録不要':yes?'登録済み':'未登録'}</span></button>`};
const ownControl=(field,label)=>{const v=effective(p,field),fixed=locked(v),yes=isOwned(v);return `<button type="button" class="status-control ${fixed?'is-fixed':yes?'is-active':''}" ${fixed?'disabled':''} data-toggle="${field}" aria-pressed="${yes}" title="${fixed?'変更できません':label+'を切り替える'}">${statusIcon('assets/images/archive-fill.svg',yes,label)}<span class="status-control-label">HOME 所持状況</span><span class="status-control-value">${fixed?'所持不可':yes?'所持':'未所持'}</span></button>`};
const related=v=>String(v||'').split(/[,、，]/).map(x=>x.trim()).filter(Boolean).map(name=>{const match=db.pokemon.find(x=>x['名前']===name);return `<button class="related-card ${match&&key(match)===id?'is-current':''}" data-related="${esc(name)}" ${match&&key(match)===id?'aria-current="true"':''} ${match?'':'disabled'}>${match?`<span class="related-status status-icons">${statusIcon('assets/images/bookmark-fill.svg',isRegistered(sh?effective(match,'shinyRegistered'):effective(match,'registered')),'図鑑登録')}${(sh?effective(match,'shiny'):effective(match,'owned'))==='不可'?'':statusIcon('assets/images/archive-fill.svg',isOwned(sh?effective(match,'shiny'):effective(match,'owned')),'所持状況')}</span><span class="related-art ${thumbnailClass(match,sh)}">${pokemonImage(match,sh)}</span>`:`<span class="related-art missing">${pokemonImage(null,false)}</span>`}<span class="related-name">${displayName(name)}</span></button>`}).join('')||'<span class="help">登録なし</span>';
const {previous,next}=detailNeighbors(id);
$('modalRoot').innerHTML=`<div class="overlay" id="overlay"><div class="modal"><div class="modal-top"><div><h2 class="detail-title detail-title-inline"><span class="detail-number">No.${esc(p['全国図鑑No'])}</span>${detailTitleName(p['名前'],sh)}</h2></div><div class="detail-top-actions"><button type="button" class="filter-close" id="detailClose" aria-label="詳細カードを閉じる" title="閉じる">×</button></div></div><div class="detail-body"><div class="detail-layout"><div class="heroimg"><div class="hero-gender" aria-label="性別">${genderLabel(p['性別'])}</div>${pokemonImage(p,sh,false)}</div><div class="detail-side"><div class="detail-facts"><div class="fact-row"><span>世代</span><div class="fact-tags"><span class="tag">${esc(generationLabel(p['世代']))}</span></div></div><div class="fact-row"><span>カテゴリ</span><div>${(categories(p).length?categories(p):['通常']).map(v=>`<span class="tag">${esc(v)}</span>`).join(' ')}</div></div><div class="fact-row"><span>実装タイトル</span><div class="fact-tags">${GAMES.filter(x=>/^(yes|true|1)$/i.test(p['実装 ('+x+')']||'')).map(x=>`<span class="tag">${esc(x)}</span>`).join('')||'<span class="tag muted">—</span>'}</div></div>${p['備考']?`<div class="fact-row"><span>備考</span><div>${esc(p['備考'])}</div></div>`:''}</div><div class="fact-row detail-tag-row"><span>タグ</span><div><div class="detail-tag-picker"><div id="detailTags" class="personal-tags"></div><select id="existingTag" aria-label="既存タグを追加"></select></div><button type="button" class="new-tag-link" id="showNewTag" aria-expanded="false" aria-controls="newTagForm">＋ 新規タグを追加</button><div class="tag-add-row" id="newTagForm" hidden><input id="newTag" placeholder="新しいタグ名" aria-label="新しいタグ名"><button type="button" class="btn" id="addTag">追加</button></div><div class="help" id="detailTagStatus" role="status"></div></div></div><div class="fields">${sh?regControl('shinyRegistered','HOME 図鑑登録（色違い）')+ownControl('shiny','HOME 所持状況（色違い）'):regControl('registered','HOME 図鑑登録')+ownControl('owned','HOME 所持状況')}</div><div class="detail-memo"><textarea id="personalMemo" class="personal-memo" rows="2" aria-label="自由メモ" placeholder="自由にメモを入力" aria-describedby="memoSaveStatus">${esc(personalMemo(p,sh))}</textarea><div class="help" id="memoSaveStatus" role="status"></div></div></div></div><div class="section"><h3>進化系</h3><div class="related">${related(p['進化系'])}</div></div><div class="section"><h3>すがた違い</h3><div class="related">${related(p['すがた違い'])}</div></div></div><div class="detail-footer"><button type="button" class="detail-nav" id="detailPrev" title="前の項目" aria-label="前の項目" ${previous?'':'disabled'}><svg viewBox="0 0 32 32" aria-hidden="true" focusable="false"><path d="M20 6 10 16 20 26"/></svg></button><button type="button" class="detail-shiny ${sh?'is-on':''}" id="detailShiny" aria-label="色違い表示" title="色違い表示" aria-pressed="${sh}"><img src="assets/images/stars.svg" alt="" class="stars-icon"><span class="shiny-label">色違い表示</span></button><button type="button" class="detail-nav" id="detailNext" title="次の項目" aria-label="次の項目" ${next?'':'disabled'}><svg viewBox="0 0 32 32" aria-hidden="true" focusable="false"><path d="m12 6 10 10-10 10"/></svg></button></div></div></div>`;
$('detailClose').onclick=closeDetail;$('showNewTag').onclick=()=>{$('newTagForm').hidden=false;$('showNewTag').setAttribute('aria-expanded','true');$('showNewTag').hidden=true;$('newTag').focus()};renderDetailTags(p,sh);$('addTag').onclick=()=>{const value=$('newTag').value.trim();if(!value)return;storeDetailTags(p,[...personalTags(p,sh),value],sh);if(personalTags(p,sh).includes(value))$('newTag').value=''};$('newTag').onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();$('addTag').click()}};
$('personalMemo').oninput=()=>{db.states[id]={...state(p),[sh?'shinyMemo':'memo']:$('personalMemo').value};try{save();$('memoSaveStatus').textContent='';render()}catch{$('memoSaveStatus').textContent='保存できませんでした。メモをコピーして保管してください。'}};
$('detailPrev').onclick=()=>{if(previous)openDetail(key(previous),sh)};$('detailNext').onclick=()=>{if(next)openDetail(key(next),sh)};$('detailShiny').onclick=()=>{const scrollTop=document.querySelector('.detail-body').scrollTop;$('shiny').checked=!sh;render();openDetail(id,!sh);document.querySelector('.detail-body').scrollTop=scrollTop};$('overlay').onclick=e=>{if(e.target.id==='overlay')closeDetail()};document.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>{if(locked(p[({owned:'HOME 所持状況',shiny:'HOME 所持状況 (色違い)'})[el.dataset.field]]))return;db.states[id]={...state(p),[el.dataset.field]:el.value};save();render();openDetail(id,sh)});document.querySelectorAll('[data-toggle]').forEach(el=>el.onclick=()=>{const field=el.dataset.toggle;const col={registered:'HOME 図鑑登録',shinyRegistered:'HOME 図鑑登録 (色違い)',owned:'HOME 所持状況',shiny:'HOME 所持状況 (色違い)'}[field];if(!col||locked(p[col]))return;const current=effective(p,field);const next=(field==='registered'||field==='shinyRegistered')?(isRegistered(current)?'No':'Yes'):(isOwned(current)?'未所持':'所持');db.states[id]={...state(p),[field]:next};save();render();openDetail(id,sh)});document.querySelectorAll('[data-related]').forEach(el=>el.onclick=()=>{let match=db.pokemon.find(x=>x['名前']===el.dataset.related);if(match)openDetail(key(match),sh)})}
document.addEventListener('keydown',e=>{if(!active||!$('overlay'))return;if(e.key==='Escape'){closeDetail();return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){const neighbors=detailNeighbors(active),target=e.key==='ArrowLeft'?neighbors.previous:neighbors.next;if(target){e.preventDefault();openDetail(key(target),$('detailShiny')?.getAttribute('aria-pressed')==='true')}}});$('shinyButton').onclick=()=>{const on=!$('shiny').checked;$('shiny').checked=on;$('shinyButton').classList.toggle('is-on',on);$('shinyButton').setAttribute('aria-pressed',String(on));render()};function closeDetail(){active=null;detailTagCandidates.clear();$('modalRoot').innerHTML='';render()}$('grid').onclick=e=>{const b=e.target.closest('[data-id]');if(b){if(bulkMode){const id=b.dataset.id;if(bulkSelection.has(id))bulkSelection.delete(id);else bulkSelection.add(id);render();[...$('grid').querySelectorAll('[data-id]')].find(el=>el.dataset.id===id)?.focus({preventScroll:true})}else openDetail(b.dataset.id)}};['search','gen','cat','registered','game','owned','memoFilter','tagFilter','genderFilter','shiny'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',()=>{if(filterDialog.open)updateFilterAppearance();else render()}));

let longPressTimer=null,longPressOrigin=null,longPressTriggered=false,suppressLongPressClick=false;
function cancelLongPress(){if(longPressTimer)clearTimeout(longPressTimer);longPressTimer=null;longPressOrigin=null}
$('grid').addEventListener('pointerdown',e=>{cancelLongPress();suppressLongPressClick=false;longPressTriggered=false;const card=e.target.closest('[data-id]');if(!card||!e.isPrimary||e.button!==0||bulkMode)return;longPressOrigin={x:e.clientX,y:e.clientY,id:card.dataset.id,pointerId:e.pointerId};longPressTimer=setTimeout(()=>{const id=longPressOrigin?.id;if(!id)return;longPressTimer=null;longPressTriggered=true;suppressLongPressClick=true;bulkToggle.click();bulkSelection.add(id);render()},300)});
document.addEventListener('pointermove',e=>{if(longPressOrigin&&e.pointerId===longPressOrigin.pointerId&&Math.hypot(e.clientX-longPressOrigin.x,e.clientY-longPressOrigin.y)>10)cancelLongPress()},{passive:true});
document.addEventListener('pointerup',()=>{cancelLongPress();if(longPressTriggered)setTimeout(()=>{suppressLongPressClick=false},600)},{passive:true});document.addEventListener('pointercancel',()=>{cancelLongPress();suppressLongPressClick=false;longPressTriggered=false},{passive:true});window.addEventListener('blur',cancelLongPress);
$('grid').addEventListener('click',e=>{if(suppressLongPressClick){suppressLongPressClick=false;e.preventDefault();e.stopImmediatePropagation()}},true);
$('grid').addEventListener('contextmenu',e=>{if(e.target.closest('[data-id]'))e.preventDefault()});

function parseCSV(text){text=text.replace(/^\ufeff/,'');let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(quoted)throw Error('CSVの引用符が閉じられていません');if(cell||row.length){row.push(cell.replace(/\r$/,''));rows.push(row)}return rows}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('backupBtn').onclick=()=>download('pokedex-personal-backup.json',{version:2,states:exportPersonalStates(),tags:allTags(),tagColors:db.tagColors});$('restoreBtn').onclick=()=>$('jsonFile').click();$('jsonFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const d=JSON.parse(await file.text());if(![1,2].includes(d.version)||!d.states||typeof d.states!=='object'||Array.isArray(d.states))throw Error('バックアップ形式が不正です');const restored=normalizeStates(d.states);const restoredTags=cleanTags(d.tags||[]),restoredColors=normalizeTagColors(d.tagColors);if(!confirm('バックアップの管理情報で現在の管理情報を置き換えます。よろしいですか？'))return;const previous=db.states,oldTags=db.tags,oldColors=db.tagColors;db.states=restored;db.tags=restoredTags;db.tagColors=restoredColors;try{save()}catch(error){db.states=previous;db.tags=oldTags;db.tagColors=oldColors;throw error}render();alert('復元しました')}catch(err){alert('復元に失敗しました：'+err.message)}finally{e.target.value=''}};

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active)closeDetail()});


function normalizeStates(states){const result=Object.create(null);for(const [id,value] of Object.entries(states)){if(!value||typeof value!=='object'||Array.isArray(value))throw Error('個人データの項目が不正です');const entry={};for(const field of ['registered','shinyRegistered','owned','shiny','memo','shinyMemo']){if(value[field]!==undefined){if(typeof value[field]!=='string')throw Error('個人データの値が不正です');entry[field]=value[field]}}if(value.tags!==undefined)entry.tags=cleanTags(value.tags);if(value.shinyTags!==undefined)entry.shinyTags=cleanTags(value.shinyTags);result[id]=entry}for(const p of db.pokemon){const aliases=[...(p['旧ID']||'').split(',').map(id=>id.trim()).filter(Boolean),p['旧キー']||p['全国図鑑No']+'|'+p['名前']];for(const alias of aliases){if(alias!==p.ID&&Object.hasOwn(result,alias)){if(!Object.hasOwn(result,p.ID))result[p.ID]=result[alias];delete result[alias]}}}return result}
function exportPersonalStates(){return {...db.states,...Object.fromEntries(db.pokemon.map(p=>[key(p),{registered:effective(p,'registered'),shinyRegistered:effective(p,'shinyRegistered'),owned:effective(p,'owned'),shiny:effective(p,'shiny'),memo:personalMemo(p,false),shinyMemo:personalMemo(p,true),tags:personalTags(p,false),shinyTags:personalTags(p,true)}]))}}
function migratePersonal(){if(storageWarning)return;let states={...db.states};if(!hasPersonalData&&legacyData&&Array.isArray(legacyData.pokemon)){for(const p of legacyData.pokemon){const alias=p['全国図鑑No']+'|'+p['名前'];const old=legacyData.states?.[alias]||{};if(!states[alias])states[alias]={registered:old.registered??p['HOME 図鑑登録']??'No',shinyRegistered:old.shinyRegistered??p['HOME 図鑑登録 (色違い)']??'No',owned:old.owned??p['HOME 所持状況']??'未所持',shiny:old.shiny??p['HOME 所持状況 (色違い)']??'未所持',memo:old.memo??p['メモ']??''}}}db.states=normalizeStates(states);save();hasPersonalData=true}
function loadCatalog(text){const rows=parseCSV(text),header=rows.shift()?.map(v=>v.trim());if(!header||['ID','名前','全国図鑑No','画像'].some(h=>!header.includes(h)))throw Error('CSVにID・名前・全国図鑑No・画像の列が必要です');if(new Set(header).size!==header.length)throw Error('CSVの列名が重複しています');if(header.some(h=>['メモ','HOME 図鑑登録','HOME 図鑑登録 (色違い)','HOME 図鑑登録 (GO)','HOME 所持状況','HOME 所持状況 (色違い)'].includes(h)))throw Error('公開CSVに個人データの列が含まれています');const ids=new Set(),aliases=new Set();const pokemon=rows.filter(r=>r.some(v=>v.trim())).map((r,i)=>{if(r.length!==header.length)throw Error('CSVの'+(i+2)+'行目の列数が一致しません');const p=Object.fromEntries(header.map((h,n)=>[h,r[n]]));p.ID=p.ID.trim();if(!/^[a-zA-Z0-9_-]+$/.test(p.ID)||ids.has(p.ID))throw Error('IDが空・重複・不正です：'+p.ID);if(!p['名前'].trim()||!p['全国図鑑No'].trim())throw Error('名前または図鑑番号が空です');ids.add(p.ID);const alias=p['旧キー']||p['全国図鑑No']+'|'+p['名前'];if(aliases.has(alias))throw Error('旧キーが重複しています：'+alias);aliases.add(alias);for(const [col,target,fixed] of [['図鑑登録対象','HOME 図鑑登録','不要'],['色違い図鑑登録対象','HOME 図鑑登録 (色違い)','不要'],['所持可能','HOME 所持状況','不可'],['色違い所持可能','HOME 所持状況 (色違い)','不可']]){const value=(p[col]||'Yes').trim();if(!/^(yes|no)$/i.test(value))throw Error(col+'はYesかNoで指定してください');p[target]=/^no$/i.test(value)?fixed:''}return p});if(!pokemon.length)throw Error('図鑑データが空です');return pokemon}
async function loadInitialPersonal(){if(hasPersonalData||storageWarning||(legacyData&&Array.isArray(legacyData.pokemon)))return;const response=await fetch('./data/default-personal.json',{cache:'no-store'});if(response.status===404)return;if(!response.ok)throw Error('初期データを取得できませんでした（'+response.status+'）');const initial=await response.json();if(initial.version!==2||!initial.states||typeof initial.states!=='object'||Array.isArray(initial.states))throw Error('初期データの形式が不正です');const states=normalizeStates(initial.states),tags=cleanTags(initial.tags||[]),colors=normalizeTagColors(initial.tagColors);db.states=states;db.tags=tags;db.tagColors=colors}
async function initializeCatalog(){const notice=$('demoNote');notice.hidden=false;notice.textContent='図鑑データを読み込んでいます…';try{if(location.protocol==='file:')throw Error('ローカルサーバーから開いてください。READMEの起動手順をご確認ください。');const response=await fetch('./data/pokemon.csv',{cache:'no-store'});if(!response.ok)throw Error('CSVを取得できませんでした（'+response.status+'）');db.pokemon=loadCatalog(await response.text());await loadInitialPersonal();try{migratePersonal()}catch{storageWarning='個人データの移行・保存ができませんでした。旧データは保持されています。バックアップをご確認ください。'}selectValues();restoreSearchState();searchStateReady=true;render();if(storageWarning){notice.hidden=false;notice.textContent=storageWarning}}catch(error){notice.hidden=false;notice.textContent='図鑑データを読み込めませんでした。'+error.message;$('grid').innerHTML='<div class="empty">data/pokemon.csvと起動方法を確認し、再読み込みしてください。</div>'}}
selectValues();render();initializeCatalog();
